{"charges": [{"claim": "Removing the dot check in hasCustomProtocol causes URLs with dot-containing custom protocols to bypass normalization, altering output.", "file": "index.js", "line": 18, "severity": "major", "witnessCode": "import x from '../index.js';

// Test that a URL with a dot in its protocol is normalized in base but left unchanged in head
const input = 'foo.bar:baz';
// Expected base behavior: protocol not recognized as custom -> default protocol prepended -> URL object -> serialized
// In base, this results in 'http:///foo.bar:baz'
// In head, the dot check is removed, so hasCustomProtocol returns true and the input is returned unchanged.
assert.strictEqual(x(input), 'http:///foo.bar:baz');"}]}
